?><?php $pageTitle=t('Compliance & Risk'); $adminCurrent='compliance'; require __DIR__ . '/partials/header.php'; ?><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2><?=e(t('Compliance & Risk'))?></h2><a href="<?=url('admin/')?>"><?=e(t('Dashboard'))?></a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><h4><?=e(t('KYC Reviews'))?></h4><div class="table-responsive mb-5"><table class="table table-sm align-middle"><thead><tr><th><?=e(t('Customer'))?></th><th><?=e(t('Name'))?></th><th><?=e(t('Document'))?></th><th><?=e(t('Status'))?></th><th><?=e(t('Review'))?></th></tr></thead><tbody><?php foreach($kycs as $k):?><tr><td><?=e($k['email'])?></td><td><?=e($k['full_name'])?></td><td><?=e($k['document_type'])?> / <?=e($k['document_reference'])?></td><td><?=e(tx_label($k['status']))?></td><td><form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="action" value="kyc"><input type="hidden" name="id" value="<?=$k['id']?>"><input name="notes" class="form-control form-control-sm" placeholder="<?=e(t('Notes'))?>"><button name="status" value="verified" class="btn btn-sm btn-success"><?=e(t('Verify'))?></button><button name="status" value="requires_review" class="btn btn-sm btn-warning"><?=e(t('Review'))?></button><button name="status" value="rejected" class="btn btn-sm btn-danger"><?=e(t('Reject'))?></button></form></td></tr><?php endforeach;?></tbody></table></div><h4><?=e(t('Open Risk Alerts'))?></h4><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th><?=e(t('Customer'))?></th><th><?=e(t('Rule'))?></th><th><?=e(t('Risk'))?></th><th><?=e(t('Score'))?></th><th><?=e(t('Reason'))?></th><th><?=e(t('Action'))?></th></tr></thead><tbody><?php foreach($alerts as $a):?><tr><td><?=e($a['email'])?></td><td><?=e($a['rule_code'])?></td><td><?=e($a['risk_level'])?></td><td><?=e((string)$a['score'])?></td><td><?=e($a['reason'])?></td><td><form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="action" value="alert"><input type="hidden" name="id" value="<?=$a['id']?>"><input name="notes" class="form-control form-control-sm" placeholder="<?=e(t('Notes'))?>"><button name="status" value="reviewing" class="btn btn-sm btn-warning"><?=e(t('Review'))?></button><button name="status" value="cleared" class="btn btn-sm btn-success"><?=e(t('Clear'))?></button><button name="status" value="blocked" class="btn btn-sm btn-danger"><?=e(t('Block'))?></button></form></td></tr><?php endforeach;?></tbody></table></div></div>
